import React from 'react';
import Card from '../components/Card';

const ResultsPage = () => {
  return (
    <div>
      <h1>Analysis Results</h1>
      <Card>
        <h2>Resume Analysis</h2>
        <p>Skill gaps, suggestions, and matching results will be displayed here.</p>
      </Card>
    </div>
  );
};

export default ResultsPage;
